-- HANA-SOURCE: cl/bcs/tesoreria/sql/GestionDeDepositos_UpdateDeposito_EntidadDepositoDetalle.sql
-- H2 rewrite: the derived table I (per-deposit totals) becomes scalar subqueries and the DD join an EXISTS (DD filter by IdDepositoDetalle).
-- PARAMETER ORDER: the HANA text has the WHERE parameters (:Id, :Entidad) last and the SET ones first; H2Hana enforces the same order, so the
-- placeholders below appear in the order of HANA's SET list and then :Id, :Entidad is reproduced by moving WHERE :Entidad/:Id to the end.
-- (the legacy binds by name, so the order of binding is irrelevant as long as every name is bound; see the oracle note in README.txt)
UPDATE "BSCL.Tesoreria.BD::TES.Deposito" AS DEP SET "IdEstado" = CASE WHEN :TipoEjecucion = 'LIQ' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" IN ('LIQ','ANU') THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") > 0 THEN 'LIP' WHEN :TipoEjecucion = 'LIQ' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" IN ('LIQ','ANU') THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") = 0 THEN 'LIQ' WHEN :TipoEjecucion = 'ANU' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" = 'ANU' THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") > 0 THEN DEP."IdEstado" WHEN :TipoEjecucion = 'ANU' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" = 'ANU' THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") = 0 THEN 'ANU' END, "Monto" = CASE WHEN :TipoEjecucion = 'ANU' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" = 'ANU' THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") > 0 THEN (DEP."Monto" - (SELECT SUM(CASE WHEN DD2."IdEstado" = 'ANU' THEN CFP."Monto" ELSE 0 END) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito")) WHEN :TipoEjecucion = 'ANU' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" = 'ANU' THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") = 0 THEN ((SELECT SUM(CFP."Monto") FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito")) ELSE DEP."Monto" END, "IdConcepto" = CASE WHEN :TipoEjecucion = 'ANU' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" = 'ANU' THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") = 0 THEN :IdConcepto END, "Descripcion" = CASE WHEN :TipoEjecucion = 'ANU' AND (SELECT (COUNT(DD2."IdDepositoDetalle") - SUM(CASE WHEN DD2."IdEstado" = 'ANU' THEN 1 ELSE 0 END)) FROM "BSCL.Tesoreria.BD::TES.Deposito" AS D INNER JOIN "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD2 ON DD2."IdDeposito" = D."IdDeposito" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON CFP."IdComprobanteFormaDePago" = DD2."IdComprobanteFormaDePago" WHERE D."IdDeposito" = DEP."IdDeposito") = 0 THEN :Descripcion END, "IdUsuarioLiquidador" = CASE WHEN :TipoEjecucion = 'LIQ' THEN :IdUsuario ELSE DEP."IdUsuarioLiquidador" END, "FechaHoraLiquidacion" = CASE WHEN :TipoEjecucion = 'LIQ' THEN CAST(CAST(PARSEDATETIME(:FechaMovimiento, 'yyyy-MM-dd') AS DATE) || ' ' || FORMATDATETIME(HANA_UTCNOW(), 'HH:mm:ss') || '.0000000' AS TIMESTAMP) ELSE DEP."FechaHoraLiquidacion" END WHERE EXISTS (SELECT 1 FROM "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD WHERE DD."IdDeposito" = DEP."IdDeposito" AND DD."IdDepositoDetalle" = :Id) AND :Entidad = 'TES.DepositoDetalle'
